using namespace std;

class Solution {
    struct TrieNode {
        int next[26] = {0};
        int count = 0;
        int depth = 0;
    };

public:
    vector<int> longestCommonPrefix(vector<string>& words, int k) {
        int n = words.size();
        if (k > n - 1) return vector<int>(n, 0);

        vector<TrieNode> trie;
        trie.push_back(TrieNode());

        for (const string& w : words) {
            int curr = 0;
            for (char ch : w) {
                int c = ch - 'a';
                if (!trie[curr].next[c]) {
                    trie[curr].next[c] = trie.size();
                    TrieNode newNode;
                    newNode.depth = trie[curr].depth + 1;
                    trie.push_back(newNode);
                }
                curr = trie[curr].next[c];
                trie[curr].count++;
            }
        }

        int max_d = 0;
        for (const auto& node : trie) {
            max_d = max(max_d, node.depth);
        }

        vector<int> depth_counts(max_d + 1, 0);
        for (size_t i = 1; i < trie.size(); ++i) {
            if (trie[i].count >= k) {
                depth_counts[trie[i].depth]++;
            }
        }

        int initial_max_d = 0;
        for (int d = max_d; d >= 0; --d) {
            if (depth_counts[d] > 0) {
                initial_max_d = d;
                break;
            }
        }

        vector<int> ans(n, 0);
        vector<int> path;
        for (int idx = 0; idx < n; ++idx) {
            path.clear();
            int curr = 0;
            for (char ch : words[idx]) {
                curr = trie[curr].next[ch - 'a'];
                path.push_back(curr);
            }

            for (int node : path) {
                if (trie[node].count == k) {
                    depth_counts[trie[node].depth]--;
                }
                trie[node].count--;
            }

            if (initial_max_d > (int)words[idx].size()) {
                ans[idx] = initial_max_d;
            } else {
                int cur = initial_max_d;
                while (cur > 0 && depth_counts[cur] == 0) {
                    cur--;
                }
                ans[idx] = cur;
            }

            for (int node : path) {
                trie[node].count++;
                if (trie[node].count == k) {
                    depth_counts[trie[node].depth]++;
                }
            }
        }

        return ans;
    }
};

