class Solution {
    static class TrieNode {
        int[] next = new int[26];
        int count = 0;
        int depth = 0;
    }

    public int[] longestCommonPrefix(String[] words, int k) {
        int n = words.length;
        if (k > n - 1) return new int[n];

        List<TrieNode> trie = new ArrayList<>();
        trie.add(new TrieNode());

        for (String w : words) {
            int curr = 0;
            for (int j = 0; j < w.length(); j++) {
                int c = w.charAt(j) - 'a';
                if (trie.get(curr).next[c] == 0) {
                    trie.get(curr).next[c] = trie.size();
                    TrieNode newNode = new TrieNode();
                    newNode.depth = trie.get(curr).depth + 1;
                    trie.add(newNode);
                }
                curr = trie.get(curr).next[c];
                trie.get(curr).count++;
            }
        }

        int maxD = 0;
        for (TrieNode node : trie) {
            maxD = Math.max(maxD, node.depth);
        }

        int[] depthCounts = new int[maxD + 1];
        for (int i = 1; i < trie.size(); i++) {
            if (trie.get(i).count >= k) {
                depthCounts[trie.get(i).depth]++;
            }
        }

        int initialMaxD = 0;
        for (int d = maxD; d >= 0; d--) {
            if (depthCounts[d] > 0) {
                initialMaxD = d;
                break;
            }
        }

        int[] ans = new int[n];
        List<Integer> path = new ArrayList<>();
        for (int idx = 0; idx < n; idx++) {
            path.clear();
            int curr = 0;
            String w = words[idx];
            for (int j = 0; j < w.length(); j++) {
                curr = trie.get(curr).next[w.charAt(j) - 'a'];
                path.add(curr);
            }

            for (int node : path) {
                if (trie.get(node).count == k) {
                    depthCounts[trie.get(node).depth]--;
                }
                trie.get(node).count--;
            }

            if (initialMaxD > w.length()) {
                ans[idx] = initialMaxD;
            } else {
                int cur = initialMaxD;
                while (cur > 0 && depthCounts[cur] == 0) {
                    cur--;
                }
                ans[idx] = cur;
            }

            for (int node : path) {
                trie.get(node).count++;
                if (trie.get(node).count == k) {
                    depthCounts[trie.get(node).depth]++;
                }
            }
        }

        return ans;
    }
}

var longestCommonPrefix = function(words, k) {
    const n = words.length;
    if (k > n - 1) return new Array(n).fill(0);

    const next = [new Map()];
    const count = [0];
    const depth = [0];

    for (const w of words) {
        let curr = 0;
        for (let j = 0; j < w.length; j++) {
            const ch = w[j];
            if (!next[curr].has(ch)) {
                const nextIdx = next.length;
                next[curr].set(ch, nextIdx);
                next.push(new Map());
                count.push(0);
                depth.push(depth[curr] + 1);
            }
            curr = next[curr].get(ch);
            count[curr]++;
        }
    }

    let maxD = 0;
    for (let i = 0; i < depth.length; i++) {
        if (depth[i] > maxD) maxD = depth[i];
    }

    const depthCounts = new Array(maxD + 1).fill(0);
    for (let i = 1; i < count.length; i++) {
        if (count[i] >= k) {
            depthCounts[depth[i]]++;
        }
    }

    let initialMaxD = 0;
    for (let d = maxD; d >= 0; d--) {
        if (depthCounts[d] > 0) {
            initialMaxD = d;
            break;
        }
    }

    const ans = new Array(n).fill(0);
    for (let idx = 0; idx < n; idx++) {
        const w = words[idx];
        const path = [];
        let curr = 0;
        for (let j = 0; j < w.length; j++) {
            curr = next[curr].get(w[j]);
            path.push(curr);
        }

        for (const node of path) {
            if (count[node] === k) {
                depthCounts[depth[node]]--;
            }
            count[node]--;
        }

        if (initialMaxD > w.length) {
            ans[idx] = initialMaxD;
        } else {
            let cur = initialMaxD;
            while (cur > 0 && depthCounts[cur] === 0) {
                cur--;
            }
            ans[idx] = cur;
        }

        for (const node of path) {
            count[node]++;
            if (count[node] === k) {
                depthCounts[depth[node]]++;
            }
        }
    }

    return ans;
};
